#!/bin/sh
# generated by cluster/overnight.py
cd "$HOME/universe-1" || exit 1
mkdir -p results/life
S=results/life/overnight_status.txt
echo "$(date -u +%FT%TZ) overnight.sh started on $(hostname)" >> $S
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/jc_4096_s1
  echo "$(date -u +%FT%TZ) start jc_4096_s1 slot 0" >> $S
  nice -n 10 life/u1life_cuda --gpu 0 --isa SWAP,ADD,NAND,JC --N 4096 --seed 1 --ticks 1000000 --report-every 1000 --income 20 --ppm-every 2000 --out-dir results/life/jc_4096_s1 --dump-final > results/life/jc_4096_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end jc_4096_s1 exit $?" >> $S
) &
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/champ512_2048_s1
  echo "$(date -u +%FT%TZ) start champ512_2048_s1 slot 1" >> $S
  nice -n 10 life/u1life_cuda --gpu 1 --isa SWAP,ADD,NAND,SKZ --N 2048 --seed 1 --ticks 1800000 --report-every 1000 --income 36 --max-steps 512 --ppm-every 4000 --out-dir results/life/champ512_2048_s1 --dump-final > results/life/champ512_2048_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end champ512_2048_s1 exit $?" >> $S
) &
(
  mkdir -p results/life/cpu_jc_512_s1
  echo "$(date -u +%FT%TZ) start cpu_jc_512_s1 slot cpu" >> $S
  nice -n 19 life/target/release/u1life --isa SWAP,ADD,NAND,JC --N 512 --seed 1 --ticks 2500000 --report-every 1000 --income 20 --ppm-every 4000 --threads 18 --out-dir results/life/cpu_jc_512_s1 --dump-final > results/life/cpu_jc_512_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end cpu_jc_512_s1 exit $?" >> $S
) &
wait
echo "$(date -u +%FT%TZ) overnight.sh finished" >> $S
